WITH trips AS (SELECT pu_location_id AS location_id, trip_id, is_airport_trip, trip_distance_miles, fare_amount, tip_amount, total_amount FROM stg_nyc_taxi_trips UNION ALL SELECT do_location_id AS location_id, trip_id, is_airport_trip, trip_distance_miles, fare_amount, tip_amount, total_amount FROM stg_nyc_taxi_trips) SELECT location_id, COUNT(DISTINCT trip_id) AS num_trips, COUNT(CASE WHEN is_airport_trip = TRUE THEN trip_id END) AS num_airport_trips, SUM(trip_distance_miles) AS total_distance_miles, SUM(fare_amount) AS total_fare_amount, SUM(tip_amount) AS total_tip_amount, SUM(total_amount) AS total_total_amount FROM trips GROUP BY location_id LIMIT 1000